import itertools
def tr(k,M):
    n=len(M)
    if k==0: return M
    if k==1: return [row[::-1] for row in M]                      # hflip
    if k==2: return M[::-1]                                        # vflip
    if k==3: return [row[::-1] for row in M[::-1]]                 # rot180
    if k==4: return [[M[n-1-j][i] for j in range(n)] for i in range(n)]  # rot90cw
    if k==5: return [[M[j][n-1-i] for j in range(n)] for i in range(n)]  # rot90ccw
    if k==6: return [[M[j][i] for j in range(n)] for i in range(n)]      # transpose
    if k==7: return [[M[n-1-j][n-1-i] for j in range(n)] for i in range(n)] # anti-transpose
