def f(g):
    n=2*len(g); N=len(g)
    M=[[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # rotate (i,j) by 90ccw repeatedly: (i,j)->(n-1-j,i) until in top-left
            a,b=i,j
            for _ in range(4):
                if a<N and b<N: break
                a,b=n-1-b,a
            M[i][j]=g[a][b]
    return M
